#include "web/web_server.hpp"

#include "measurement/measurement_controller.hpp"
#include "wifi/wifi_manager.hpp"
#include "esp_http_server.h"
#include "esp_log.h"
#include <cctype>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>

namespace {
constexpr char TAG[] = "web";
const char PAGE[] = R"HTML(<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NeedleMeter</title><style>body{font:16px system-ui;margin:24px;max-width:1000px;color:#17212b}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.card{padding:14px;border:1px solid #d4d9df;border-radius:10px}.big{font-size:24px;font-weight:700}.ok{color:#087f3b}.bad{color:#b42318}button{padding:10px;margin:4px}label{display:block;margin:7px 0}input{float:right;width:125px}#msg{min-height:24px}</style><h1>NeedleMeter</h1><p id="msg"></p><div class="grid"><section class="card"><b>Последнее измерение</b><div class="big" id="length">—</div><div>Результат: <b id="result"></b></div><div>Номинал: <b id="nominal"></b></div><div>Допуск: <b id="tolerance"></b></div><div>Фаза: <b id="phase"></b></div></section><section class="card"><b>Автоматический режим</b><div>Режим: <b id="auto"></b></div><div>Автофаза: <b id="auto_phase"></b></div><div>Калибровка: <b id="cal_source"></b></div><div>Опорная длина: <b id="cal_ref"></b></div><p><button onclick="cmd('auto/start')">Включить AUTO</button><button onclick="cmd('auto/stop')">Выключить AUTO</button></p></section><section class="card"><b>Датчики и сеть</b><div>Игла: <span id="needle"></span></div><div>CONTACT: <span id="contact"></span></div><div>STOP: <span id="stop"></span></div><div>Ошибка: <b id="error"></b></div><div>Wi‑Fi: <span id="wifi"></span></div><div>IP: <b id="ip"></b></div></section></div><p><button id="measure" onclick="cmd('measure')">Измерить</button><button id="calibrate" onclick="cmd('calibrate')">Калибровать</button><button onclick="cmd('reset-stop')">Сброс STOP</button><button onclick="cmd('reset-error')">Сброс ошибки</button><button onclick="cmd('factory-reset')">Заводские настройки</button></p><h2>Настройки оператора</h2><form id="cfg" class="grid"></form><p><button onclick="save();return false">Сохранить</button></p><script>const fields=['nominal_length_mm','tolerance_mm','calibration_length_mm','auto_calibration_length_mm','retract_mm','measure_dir_inverted'];const labels={nominal_length_mm:'Номинальная длина, мм',tolerance_mm:'Допуск ±, мм',calibration_length_mm:'Длина ручного калибра, мм',auto_calibration_length_mm:'Длина автокалибра, мм',retract_mm:'Обычный отъезд, мм',measure_dir_inverted:'Инвертировать DIR'};function msg(x,b=false){let e=document.querySelector('#msg');e.textContent=x;e.className=b?'bad':'ok'}function put(s){let v={phase:s.state,auto:s.auto_mode_enabled?'ВКЛ':'ВЫКЛ',auto_phase:s.auto_phase,cal_source:s.calibration_source,cal_ref:s.calibration_reference_length_mm.toFixed(3)+' мм',error:s.error,length:s.last_length_mm==null?'—':s.last_length_mm.toFixed(3)+' мм',result:s.result,nominal:s.nominal_length_mm.toFixed(3)+' мм',tolerance:'±'+s.tolerance_mm.toFixed(3)+' мм',needle:s.needle_present?'обнаружена':'отсутствует',contact:s.contact?'замкнут':'свободен',stop:s.stop_active?'АКТИВЕН':'нормально',wifi:s.wifi_mode+(s.wifi_connected?' подключён':' отключён'),ip:s.ip_address||'—'};for(let[k,x]of Object.entries(v))document.querySelector('#'+k).textContent=x;document.querySelector('#measure').disabled=s.auto_mode_enabled;document.querySelector('#calibrate').disabled=s.auto_mode_enabled}async function status(){try{let r=await fetch('/api/status');if(!r.ok)throw Error();put(await r.json())}catch(e){msg('Нет связи с устройством',true)}}async function load(){let c=await(await fetch('/api/config')).json(),f=document.querySelector('#cfg');f.innerHTML='';for(let k of fields){let b=typeof c[k]==='boolean';f.insertAdjacentHTML('beforeend','<label>'+labels[k]+' <input id="'+k+'" type="'+(b?'checkbox':'number')+'" '+(b&&c[k]?'checked':'')+' value="'+(b?'1':c[k])+'" step="any"></label>')}}async function cmd(x){let r=await fetch('/api/'+x,{method:'POST'});msg(r.ok?'Команда принята':await r.text(),!r.ok)}async function save(){let x={};for(let k of fields){let e=document.querySelector('#'+k);x[k]=e.type==='checkbox'?e.checked:Number(e.value)}let r=await fetch('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(x)});msg(r.ok?'Настройки сохранены':await r.text(),!r.ok)}load();status();setInterval(status,500)</script></html>)HTML";
WebContext *context(httpd_req_t *r) { return static_cast<WebContext *>(r->user_ctx); }
esp_err_t json(httpd_req_t *r, const char *body) { httpd_resp_set_type(r, HTTPD_TYPE_JSON); return httpd_resp_sendstr(r, body); }
esp_err_t root(httpd_req_t *r) { httpd_resp_set_type(r, "text/html; charset=utf-8"); return httpd_resp_send(r, PAGE, HTTPD_RESP_USE_STRLEN); }
const char *calibration_source_name(CalibrationSource s) { return s == CalibrationSource::Auto ? "AUTO" : s == CalibrationSource::Manual ? "MANUAL" : "NONE"; }
bool snapshot(httpd_req_t *r, StatusSnapshot &m, WifiStatus &w) { auto *c = context(r); return c && c->controller && c->wifi && c->controller->snapshot(m) && ((w = c->wifi->snapshot()), true); }
esp_err_t status(httpd_req_t *r) { StatusSnapshot m{}; WifiStatus w{}; if (!snapshot(r,m,w)) return httpd_resp_send_err(r,HTTPD_500_INTERNAL_SERVER_ERROR,"Controller unavailable"); char b[1800]; int n=std::snprintf(b,sizeof(b),"{\"state\":\"%s\",\"error\":\"%s\",\"needle_present\":%s,\"contact\":%s,\"stop_active\":%s,\"motor_enabled\":%s,\"auto_mode_enabled\":%s,\"auto_phase\":\"%s\",\"current_speed_steps_s\":%lu,\"position_steps\":%lld,\"last_length_mm\":%.6f,\"nominal_length_mm\":%.6f,\"deviation_mm\":%.6f,\"tolerance_mm\":%.6f,\"result\":\"%s\",\"calibration_valid\":%s,\"calibration_source\":\"%s\",\"calibration_reference_length_mm\":%.6f,\"wifi_mode\":\"%s\",\"wifi_connected\":%s,\"ip_address\":\"%s\"}",state_name(m.state),error_name(m.error),m.needle_present?"true":"false",m.contact?"true":"false",m.stop_active?"true":"false",m.motor_enabled?"true":"false",m.auto_mode_enabled?"true":"false",m.auto_phase,static_cast<unsigned long>(m.current_speed_steps_s),static_cast<long long>(m.position_steps),m.stats.last_measured_length,m.config.nominal_length_mm,m.stats.last_deviation,m.config.tolerance_mm,m.stats.last_result,m.stats.calibration_valid?"true":"false",calibration_source_name(m.stats.calibration_source),m.stats.calibration_reference_length_mm,wifi_mode_name(w.mode),w.connected?"true":"false",w.ip_address); return n<0||static_cast<size_t>(n)>=sizeof(b)?ESP_ERR_NO_MEM:json(r,b); }
esp_err_t get_config(httpd_req_t *r) { StatusSnapshot m{}; WifiStatus w{}; if(!snapshot(r,m,w))return httpd_resp_send_err(r,HTTPD_500_INTERNAL_SERVER_ERROR,"Controller unavailable"); char b[512]; int n=std::snprintf(b,sizeof(b),"{\"nominal_length_mm\":%.6f,\"tolerance_mm\":%.6f,\"calibration_length_mm\":%.6f,\"auto_calibration_length_mm\":%.6f,\"retract_mm\":%.6f,\"measure_dir_inverted\":%s}",m.config.nominal_length_mm,m.config.tolerance_mm,m.config.calibration_length_mm,m.config.auto_calibration_length_mm,m.config.retract_mm,m.config.measure_dir_inverted?"true":"false");return n<0||static_cast<size_t>(n)>=sizeof(b)?ESP_ERR_NO_MEM:json(r,b); }
const char *value(const char *b,const char *k){char n[64];int x=std::snprintf(n,sizeof(n),"\"%s\"",k);if(x<0||static_cast<size_t>(x)>=sizeof(n))return nullptr;const char*p=std::strstr(b,n);if(!p)return nullptr;p+=x;while(std::isspace(static_cast<unsigned char>(*p)))++p;if(*p++!=':')return nullptr;while(std::isspace(static_cast<unsigned char>(*p)))++p;return p;}
bool number(const char *p,double &v){if(!p)return false;char*e=nullptr;v=std::strtod(p,&e);if(e==p||!std::isfinite(v))return false;while(std::isspace(static_cast<unsigned char>(*e)))++e;return *e==','||*e=='}'||!*e;}
bool optional_double(const char*b,const char*k,double&v){const char*p=value(b,k);if(!p)return true;double q; if(!number(p,q))return false;v=q;return true;}
bool optional_bool(const char*b,const char*k,bool&v){const char*p=value(b,k);if(!p)return true; if(std::strncmp(p,"true",4)==0){v=true;return true;}if(std::strncmp(p,"false",5)==0){v=false;return true;}return false;}
bool body(httpd_req_t*r,char*b,size_t z){if(r->content_len<=0||static_cast<size_t>(r->content_len)>=z)return false;int o=0;while(o<r->content_len){int q=httpd_req_recv(r,b+o,r->content_len-o);if(q<=0)return false;o+=q;}b[o]=0;return true;}
esp_err_t post_config(httpd_req_t*r){char b[1024];if(!body(r,b,sizeof(b)))return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"Invalid body");StatusSnapshot m{};WifiStatus w{};if(!snapshot(r,m,w))return httpd_resp_send_err(r,HTTPD_500_INTERNAL_SERVER_ERROR,"Controller unavailable");DeviceConfig c=m.config;bool ok=optional_double(b,"nominal_length_mm",c.nominal_length_mm)&&optional_double(b,"tolerance_mm",c.tolerance_mm)&&optional_double(b,"calibration_length_mm",c.calibration_length_mm)&&optional_double(b,"auto_calibration_length_mm",c.auto_calibration_length_mm)&&optional_double(b,"retract_mm",c.retract_mm)&&optional_bool(b,"measure_dir_inverted",c.measure_dir_inverted);const char*why=nullptr;auto*x=context(r);if(!ok||!x||!x->controller||!x->controller->update_config(c,&why))return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,why?why:"Settings rejected");return json(r,"{\"ok\":true}");}
esp_err_t command(httpd_req_t*r){auto*c=context(r);if(!c||!c->controller)return httpd_resp_send_err(r,HTTPD_500_INTERNAL_SERVER_ERROR,"Controller unavailable");const char*u=r->uri;CommandType t=std::strstr(u,"auto/start")?CommandType::AutoStart:std::strstr(u,"auto/stop")?CommandType::AutoStop:std::strstr(u,"measure")?CommandType::Measure:std::strstr(u,"calibrate")?CommandType::Calibrate:std::strstr(u,"reset-stop")?CommandType::ResetStop:std::strstr(u,"reset-error")?CommandType::ResetError:CommandType::FactoryReset;if(!c->controller->enqueue(t)){httpd_resp_set_status(r,"503 Service Unavailable");return json(r,"{\"error\":\"Command queue full\"}");}return json(r,"{\"accepted\":true}");}
}
esp_err_t WebServer::start(MeasurementController *controller, WifiManager *wifi){if(!controller||!wifi)return ESP_ERR_INVALID_ARG;if(server_)return ESP_ERR_INVALID_STATE;context_={controller,wifi};httpd_config_t c=HTTPD_DEFAULT_CONFIG();c.max_uri_handlers=12;httpd_handle_t s=nullptr;esp_err_t e=httpd_start(&s,&c);if(e!=ESP_OK)return e;const httpd_uri_t u[]={{.uri="/",.method=HTTP_GET,.handler=root,.user_ctx=&context_},{.uri="/api/status",.method=HTTP_GET,.handler=status,.user_ctx=&context_},{.uri="/api/config",.method=HTTP_GET,.handler=get_config,.user_ctx=&context_},{.uri="/api/config",.method=HTTP_POST,.handler=post_config,.user_ctx=&context_},{.uri="/api/measure",.method=HTTP_POST,.handler=command,.user_ctx=&context_},{.uri="/api/calibrate",.method=HTTP_POST,.handler=command,.user_ctx=&context_},{.uri="/api/auto/start",.method=HTTP_POST,.handler=command,.user_ctx=&context_},{.uri="/api/auto/stop",.method=HTTP_POST,.handler=command,.user_ctx=&context_},{.uri="/api/reset-stop",.method=HTTP_POST,.handler=command,.user_ctx=&context_},{.uri="/api/reset-error",.method=HTTP_POST,.handler=command,.user_ctx=&context_},{.uri="/api/factory-reset",.method=HTTP_POST,.handler=command,.user_ctx=&context_}};for(const auto&x:u){e=httpd_register_uri_handler(s,&x);if(e!=ESP_OK){httpd_stop(s);return e;}}server_=s;ESP_LOGI(TAG,"HTTP server started");return ESP_OK;}
